local KTool = CS.Engine.Lib.KTool
local ResourceModule = CS.Engine.Modules.ResourceModule
local cs_coroutine     = require "XLua.cs_coroutine"
local Quaternion = CS.UnityEngine.Quaternion
local Vector3           = Vector3

local MaidCoffeeBusinessController = Class('MaidCoffeeBusinessController')
local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
local MaidCoffeeUtils = import("Game.MaidCoffee.MaidCoffeeUtils")
function MaidCoffeeBusinessController:__init()
    self._isInitComplete = false
    self.businessData = nil
    self.rootGo = nil
    self.playNode = nil
    self.uiParent = nil
    self.camera = nil
end

function MaidCoffeeBusinessController:__delete()
    self._isInitComplete = nil
    self:CleanCache()
end

function MaidCoffeeBusinessController:CleanCache()
    self.businessData = nil
    self.rootGo = nil
    self.playNode = nil
    self.uiParent = nil
    self.camera = nil
    if not isNull(self._co) then
        cs_coroutine.stop(self._co)
        self._co = nil
    end

    if not isNull(self.businessGo) then
        KTool.SafeDelete(self.businessGo,true)
        self.businessGo = nil
    end

    if not isNull(self._bubbleGo) then
        KTool.SafeDelete(self._bubbleGo,true)
        self._bubbleGo = nil
    end
end

function MaidCoffeeBusinessController:Awake()
end

---@param rootGo UnityEngine.Transform 商人挂载点
---@param playNode UnityEngine.Transform 主角
---@param uiParent UnityEngine.GameObject 头顶UI父节点
---@param camera UnityEngine.Camera 跟随主角的相机
function MaidCoffeeBusinessController:Init(rootGo,playNode,uiParent,camera)
    local modelData = self:GetModelData()
    if isNull(modelData.merchant) or (not next(modelData.merchant)) then
        self:Delete()
        return
    end
    self.businessData = modelData
    self.rootGo = rootGo
    self.playNode = playNode
    self.uiParent = uiParent
    self.camera = camera

    if not isNull(self.businessData.merchant.modelId) and self.businessData.merchant.modelId ~= "" then
        local modelPath = CS.ParseUtils.ParsePathNameByData(self.businessData.merchant.modelId)
        self:AddModel(modelPath,self.rootGo)
    else
        self._initComplete = true
    end
end

function MaidCoffeeBusinessController:AddModel(prefabPath,parent)
    if string.isEmpty(prefabPath) then
        return nil
    end
    ResourceModule.LoadBundleAsync(prefabPath, function(_loader, isOk, resultObject)
        if isOk then
            local go = _loader:Instantiate()
            if not isNull(go) then
                KTool.SetParent(go,parent.gameObject,false)
                KTool.SetLayer(parent.gameObject, go.gameObject, true)
                local navMeshObstacle = KTool.GetOrAddComponent(go.gameObject,typeof(CS.UnityEngine.AI.NavMeshObstacle))
                navMeshObstacle.carving = true
                self.businessGo = go
                ---等客人出来以后再来刷新头显  防止头显先刷出来 找不到客人
                self:CreateBubbleNode(self.uiParent,self.businessData.merchant.id)
            end
        end
    end)
end

function MaidCoffeeBusinessController:CreateBubbleNode(parent, npcId)
    if isNull(parent) then return end
    self:RemoveCreateCo()
    self._co = cs_coroutine.start(function ()
        local bubbleName = "Bubble" .. npcId
        local go = parent.transform:Find(bubbleName)
        if not isNull(go) then
            self:OnEventCreateBubbleSuccess(npcId,go)
            self._initComplete = true
            return
        end
        local MaidCoffeeConstants = MaidCoffeeConstants
        go = GameUtils.LoadBundleAsync(MaidCoffeeConstants.PrefabPath.BubblePath, parent, false)
        if not isNull(parent) and not isNull(go) then
            go.name = bubbleName
            KTool.SetLayer(parent.gameObject, go, true)
            self:OnEventCreateBubbleSuccess(npcId,go)
            self._initComplete = true
        end
    end)
end

function MaidCoffeeBusinessController:FreshBubbleNodePosition()
    if not self._initComplete then return end
    if isNull(self._bubbleGo) then return end
    local bubbleTrans = self._bubbleGo.transform
    local position = self.rootGo.transform.position
    position.y = position.y + 2
    local isChange = Vector3.Distance(bubbleTrans.position, position) > 0.001
    if isChange then
        bubbleTrans.position = position
        local fwd = self.businessGo.transform.forward
        bubbleTrans.localRotation = Quaternion.LookRotation(fwd)
    end
    -- 让 ui元素始终朝向 mainCamera
    local mainCamera = CS.Game.Native.URP.URPCameraController.Instance.mainCamera
    local lookAtPos = bubbleTrans.position + mainCamera.transform.rotation * Vector3.unity_vector3.back
    local worldUpDir = mainCamera.transform.rotation * Vector3.unity_vector3.up
    bubbleTrans:LookAt( lookAtPos, worldUpDir )
    bubbleTrans:Rotate( 0.0, 180.0, 0.0 )
    return isChange
end

function MaidCoffeeBusinessController:OnEventCreateBubbleSuccess(npcId, go)
    if self.businessData.merchant.id ~= npcId then
        return
    end
    self._bubbleGo = go
    self:FreshBubbleNodePosition()
    ---@type MapDecryptionRoleDialogueBubble
    local env = CfUtils.GetLuaScr(go, MaidCoffeeConstants.EnvPath.BubbleNode)
    if not isNull(env) then
        env:SetCallBack(Bind(self,self.OnBusinessHudClick))
        env:RefreshNameAndTitle(self.businessData.merchant.name,"",2)
    end
end

function MaidCoffeeBusinessController:OnBusinessHudClick()
    Events.Broadcast(MaidCoffeeConstants.EventNames.MaidCoffeeGoToPosition,{type = "MaidCoffeeBusiness"})
end

function MaidCoffeeBusinessController:RemoveCreateCo()
    if not isNull(self._co) then
        cs_coroutine.stop(self._co)
        self._co = nil
    end
end


function MaidCoffeeBusinessController:IsNear()
    if not self._initComplete then return end
    if isNull(self.playNode) then return end
    if isNull(self.rootGo) then return end

    local dis = Vector3.Distance(self.rootGo.position, self.playNode.position)
    local roleAngle = MaidCoffeeUtils.CalcAngleAndClockwise(self.playNode.forward, self.rootGo.position, self.playNode.position)

    if dis <= MaidCoffeeConstants.NearDistance and roleAngle < 90 then
        return true
    end
    return false
end

function MaidCoffeeBusinessController:GetModelData()
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
    local data = maidCoffeeHomeDojo:GetMerchantData()
    return data
end

function MaidCoffeeBusinessController:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return MaidCoffeeBusinessController